import React, { useEffect, useState } from "react";
import { Html5QrcodeScanner } from "html5-qrcode";
import axios from "axios";

function QRScanner() {
  const [message, setMessage] = useState("");
  const [user, setUser] = useState(null);

  useEffect(() => {
    const scanner = new Html5QrcodeScanner(
      "reader",
      {
        fps: 10,
        qrbox: { width: 250, height: 250 },
      },
      false,
    );

    scanner.render(
      (decodedText) => {
        console.log("QR SCANNED:", decodedText);

        verifyUser(decodedText);
      },

      (error) => {
        // ignore scanning errors
      },
    );

    return () => {
      scanner.clear().catch(() => {});
    };
  }, []);

  const verifyUser = async (id) => {
    try {
      const res = await axios.get(`http://localhost:5000/verify-user/${id}`);

      if (res.data.success) {
        setUser(res.data.user);

        setMessage("✅ VERIFIED");

        await axios.post("http://localhost:5000/mark-attendance", {
          name: res.data.user.name,
          event_id: res.data.user.event_id,
          phone: res.data.user.phone,
        });
      } else {
        setUser(null);

        setMessage("❌ NOT REGISTERED");
      }
    } catch (err) {
      console.log(err);

      setMessage("⚠ SERVER ERROR");
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Admin QR Scanner</h2>

      <div id="reader" style={{ width: "350px" }}></div>

      <h3>{message}</h3>

      {user && (
        <div>
          <p>Name: {user.name}</p>
          <p>College: {user.college_name}</p>
          <p>Phone: {user.phone}</p>
          <p>Event ID: {user.event_id}</p>
        </div>
      )}
    </div>
  );
}

export default QRScanner;
